import asyncio

async def act(page):
    # Click on the homepage link using a specific locator to avoid strict mode violation
    homepage_link = page.get_by_role('banner').get_by_role('link', name='Epoch & Drift Benchmark')
    await homepage_link.click()
    await asyncio.sleep(5)  # Wait for page to load

    # Use filter_pages_by_content_type on the homepage to get links without further navigation
    links_by_type = await filter_pages_by_content_type(page, '/')

    # Search for the target article in the links
    target_title = 'Building A PC, Part IX: Downsizing'
    found_url = None

    for category, links in links_by_type.items():
        for link in links:
            if 'name' in link and 'url' in link:
                if target_title.lower() in link['name'].lower():
                    found_url = link['url']
                    break
        if found_url:
            break

    if found_url:
        return found_url
    else:
        return 'Article not found'

